  [250952] = { "壊れやすい調合物を対象の範囲に投げつけ、$D1の間Disorienting Smogの雲を発生させます。雲の中に立っている敵はHit Chanceが$N2%低下します。レベル$N3より高い対象には効果がありません。", 0x9e622aba, "u" },
  [250953] = { "ドラゴンの炎のげっぷを放ち、前方の狭い円錐範囲内に即座に$N1のFireダメージを与えます。効果を受けた対象は$D2の間、$N3秒ごとに$N2の追加ダメージを受けます。", 0x416cdf81, "u" },
  [250954] = { "Elementalに対するSpell Damageが$N1上昇します。持続時間は$D1です。", 0x6b518420, "u" },
  [250955] = { "Beastsに対するAttack Powerを$N1増加させます。持続時間は$D1です。", 0xc2c3cf7e, "u" },
